import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  sessions: defineTable({
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  }).index("by_expiresAt", ["expiresAt"]),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const createSession = mutation({
  args: {
    runId: v.string(),
    expiresAt: v.number(),
    isActive: v.boolean(),
  },
  handler: async (ctx, args) => {
    const id = await ctx.db.insert("sessions", args);
    return id;
  },
});

export const getSession = query({
  args: { id: v.id("sessions") },
  handler: async (ctx, args) => {
    return await ctx.db.get(args.id);
  },
});

export const cleanupExpiredSessions = mutation({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const expiredSessions = await ctx.db
      .query("sessions")
      .withIndex("by_expiresAt", (q) => q.lt("expiresAt", now))
      .filter((q) => q.eq(q.field("isActive"), true))
      .collect();

    for (const session of expiredSessions) {
      await ctx.db.patch(session._id, { isActive: false });
    }
  },
});

import { cronJobs } from "convex/server";
import { api } from "./_generated/api";

const crons = cronJobs();

crons.interval(
  "cleanup expired sessions",
  { minutes: 1 },
  api.sessions.cleanupExpiredSessions,
);

export default crons;

const { ConvexHttpClient } = require("convex/browser");
const { api } = require("./convex/_generated/api");

const CONVEX_URL = process.env.CONVEX_URL;

if (!CONVEX_URL) {
  console.error("CONVEX_URL environment variable is not set");
  process.exit(1);
}

const client = new ConvexHttpClient(CONVEX_URL);

async function main() {
  const args = process.argv.slice(2);
  const runIdIndex = args.indexOf("--run-id");
  if (runIdIndex === -1 || !args[runIdIndex + 1]) {
    console.error("Usage: node seed.js --run-id <run-id>");
    process.exit(1);
  }
  const runId = args[runIdIndex + 1];

  // Set expiresAt to 1 minute ago
  const expiresAt = Date.now() - 60000;

  const sessionId = await client.mutation(api.sessions.createSession, {
    runId,
    expiresAt,
    isActive: true,
  });

  console.log(`Session ID: ${sessionId}`);
}

main().catch(console.error);

const { ConvexHttpClient } = require("convex/browser");
const { api } = require("./convex/_generated/api");

const CONVEX_URL = process.env.CONVEX_URL;

if (!CONVEX_URL) {
  console.error("CONVEX_URL environment variable is not set");
  process.exit(1);
}

const client = new ConvexHttpClient(CONVEX_URL);

async function main() {
  const args = process.argv.slice(2);
  const idIndex = args.indexOf("--id");
  if (idIndex === -1 || !args[idIndex + 1]) {
    console.error("Usage: node check.js --id <session-id>");
    process.exit(1);
  }
  const sessionId = args[idIndex + 1];

  const session = await client.query(api.sessions.getSession, { id: sessionId });

  if (!session) {
    console.error("Session not found");
    process.exit(1);
  }

  console.log(`Is Active: ${session.isActive}`);
}

main().catch(console.error);
